import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    def is_header(row: List[str]) -> bool:
        normalized = [cell.strip().casefold() for cell in row]
        return (
            "date of payment" in normalized
            and "expense type" in normalized
            and ("amount" in normalized or "supplier" in normalized)
        )

    header_index = next(
        (index for index, row in enumerate(records) if is_header(row)),
        None,
    )

    if header_index is not None:
        columns = list(records[header_index])
        data_records = records[header_index + 1:]
    else:
        first_record = next(
            (index for index, row in enumerate(records) if any(cell.strip() for cell in row)),
            None,
        )
        if first_record is None:
            return {"columns": [], "rows": []}
        columns = list(records[first_record])
        data_records = records[first_record + 1:]

    width = len(columns)
    if width == 0:
        return {"columns": [], "rows": []}

    if len(columns) < width:
        columns.extend([""] * (width - len(columns)))
    elif len(columns) > width:
        columns = columns[:width]

    amount_pattern = re.compile(
        r"^[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?$"
    )

    def repair_row(row: List[str]) -> List[str]:
        if len(row) < width:
            return row + [""] * (width - len(row))
        if len(row) == width:
            return row

        # In this file, the first five fields and final month field are stable.
        # Reassemble an unquoted amount containing thousands separators where possible.
        if width == 8 and len(row) > 8:
            month = row[-1]
            amount_start = None
            for start in range(5, len(row) - 1):
                candidate = ",".join(row[start:-1]).strip()
                if amount_pattern.fullmatch(candidate):
                    amount_start = start
                    break

            if amount_start is not None:
                supplier = ",".join(row[5:amount_start])
                amount = ",".join(row[amount_start:-1])
                return row[:5] + [supplier, amount, month]

            supplier = ",".join(row[5:-2])
            return row[:5] + [supplier, row[-2], month]

        # Preserve extra fields in the final column rather than discarding data.
        return row[:width - 1] + [",".join(row[width - 1:])]

    rows = [
        repair_row(row)
        for row in data_records
        if row and any(cell.strip() for cell in row)
    ]

    return {"columns": columns, "rows": rows}
